-- Run after teams.sql in Supabase Dashboard > SQL Editor.
-- Payment references are currently generated by the prototype client. Replace
-- registration confirmation with a verified payment-provider webhook before launch.

create table if not exists public.tournaments (
  event_key text primary key,
  name text not null,
  sport text not null,
  registration_fee integer not null check (registration_fee >= 0),
  gender_filter text not null default 'Open to all',
  age_filter text not null default 'All ages',
  min_team_members integer not null default 1 check (min_team_members > 0),
  max_team_slots integer not null default 100 check (max_team_slots > 0),
  created_at timestamptz not null default now()
);

insert into public.tournaments(event_key, name, sport, registration_fee, gender_filter, age_filter, min_team_members, max_team_slots)
values
  ('sunday-five-a-side', 'Sunday 5-a-side Cup', 'Football', 1200, 'Open to all', '18-35', 5, 3),
  ('playyr-city-showdown', 'PLAYYR City Showdown', 'BGMI', 399, 'Open to all', 'All ages', 4, 12),
  ('open-doubles-night', 'Open Doubles Night', 'Badminton', 600, 'Mixed teams', '18-35', 2, 7)
on conflict (event_key) do update set
  name = excluded.name,
  sport = excluded.sport,
  registration_fee = excluded.registration_fee,
  gender_filter = excluded.gender_filter,
  age_filter = excluded.age_filter,
  min_team_members = excluded.min_team_members,
  max_team_slots = excluded.max_team_slots;

create table if not exists public.tournament_team_registrations (
  id uuid primary key default gen_random_uuid(),
  tournament_key text not null references public.tournaments(event_key) on delete cascade,
  team_id uuid not null references public.teams(id) on delete cascade,
  registered_by uuid not null references auth.users(id) on delete cascade,
  amount_paid integer not null check (amount_paid >= 0),
  payment_reference text not null unique,
  status text not null default 'confirmed' check (status in ('confirmed', 'cancelled', 'refunded')),
  registered_at timestamptz not null default now(),
  unique (tournament_key, team_id)
);

alter table public.tournaments enable row level security;
alter table public.tournament_team_registrations enable row level security;

drop policy if exists "authenticated users can view tournaments" on public.tournaments;
create policy "authenticated users can view tournaments" on public.tournaments
for select to authenticated using (true);

drop policy if exists "team members can view registrations" on public.tournament_team_registrations;
create policy "team members can view registrations" on public.tournament_team_registrations
for select to authenticated using (public.is_team_member(team_id));

create or replace function public.check_team_tournament_eligibility(p_team_id uuid, p_tournament_key text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  selected_team public.teams%rowtype;
  selected_tournament public.tournaments%rowtype;
  roster_size integer;
  missing_details integer;
  ineligible_age integer;
  male_count integer;
  female_count integer;
  ineligible_gender integer;
begin
  if auth.uid() is null then return jsonb_build_object('eligible', false, 'message', 'Sign in to register a team.'); end if;
  select * into selected_team from public.teams where id = p_team_id;
  if not found then return jsonb_build_object('eligible', false, 'message', 'Team not found.'); end if;
  if selected_team.creator_id <> auth.uid() then return jsonb_build_object('eligible', false, 'message', 'Only the team creator can register this team.'); end if;
  select * into selected_tournament from public.tournaments where event_key = p_tournament_key;
  if not found then return jsonb_build_object('eligible', false, 'message', 'Tournament not found.'); end if;
  if lower(selected_team.sport) <> lower(selected_tournament.sport) then
    return jsonb_build_object('eligible', false, 'message', 'This tournament is for ' || selected_tournament.sport || ' teams.');
  end if;

  select count(*) into roster_size from public.team_members where team_id = p_team_id;
  if roster_size < selected_tournament.min_team_members then
    return jsonb_build_object('eligible', false, 'message', 'This tournament requires at least ' || selected_tournament.min_team_members || ' team members.');
  end if;

  select count(*) into missing_details
  from public.team_members m left join public.profiles p on p.id = m.user_id
  where m.team_id = p_team_id
    and ((selected_tournament.age_filter <> 'All ages' and p.birth_date is null)
      or (selected_tournament.gender_filter <> 'Open to all' and nullif(trim(p.gender), '') is null));
  if missing_details > 0 then
    return jsonb_build_object('eligible', false, 'message', missing_details || ' member(s) must complete their age and gender profile details.');
  end if;

  select count(*) into ineligible_age
  from public.team_members m join public.profiles p on p.id = m.user_id
  where m.team_id = p_team_id and case selected_tournament.age_filter
    when 'Under 14' then date_part('year', age(current_date, p.birth_date)) >= 14
    when 'Under 18' then date_part('year', age(current_date, p.birth_date)) >= 18
    when '18-25' then date_part('year', age(current_date, p.birth_date)) not between 18 and 25
    when '26-35' then date_part('year', age(current_date, p.birth_date)) not between 26 and 35
    when '18-35' then date_part('year', age(current_date, p.birth_date)) not between 18 and 35
    when '35+' then date_part('year', age(current_date, p.birth_date)) < 35
    else false end;
  if ineligible_age > 0 then
    return jsonb_build_object('eligible', false, 'message', ineligible_age || ' member(s) do not meet the ' || selected_tournament.age_filter || ' age requirement.');
  end if;

  select
    count(*) filter (where lower(p.gender) = 'male'),
    count(*) filter (where lower(p.gender) = 'female'),
    count(*) filter (where
      (selected_tournament.gender_filter = 'Men' and lower(p.gender) <> 'male') or
      (selected_tournament.gender_filter = 'Women' and lower(p.gender) <> 'female'))
  into male_count, female_count, ineligible_gender
  from public.team_members m join public.profiles p on p.id = m.user_id
  where m.team_id = p_team_id;

  if ineligible_gender > 0 then
    return jsonb_build_object('eligible', false, 'message', 'One or more members do not meet the ' || selected_tournament.gender_filter || ' gender requirement.');
  end if;
  if selected_tournament.gender_filter = 'Mixed teams' and (male_count = 0 or female_count = 0) then
    return jsonb_build_object('eligible', false, 'message', 'Mixed-team events require at least one male and one female member.');
  end if;

  return jsonb_build_object('eligible', true, 'message', 'All ' || roster_size || ' members meet the sport, age and gender requirements.');
end;
$$;

revoke all on function public.check_team_tournament_eligibility(uuid, text) from public;
grant execute on function public.check_team_tournament_eligibility(uuid, text) to authenticated;

create or replace function public.register_team_for_tournament(p_team_id uuid, p_tournament_key text, p_payment_reference text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  eligibility jsonb;
  selected_tournament public.tournaments%rowtype;
  confirmed_count integer;
begin
  if auth.uid() is null then raise exception 'Sign in to register a team'; end if;
  eligibility := public.check_team_tournament_eligibility(p_team_id, p_tournament_key);
  if not coalesce((eligibility ->> 'eligible')::boolean, false) then raise exception '%', eligibility ->> 'message'; end if;
  if nullif(trim(p_payment_reference), '') is null then raise exception 'Payment was not completed'; end if;
  select * into selected_tournament from public.tournaments where event_key = p_tournament_key for update;
  select count(*) into confirmed_count from public.tournament_team_registrations where tournament_key = p_tournament_key and status = 'confirmed';
  if confirmed_count >= selected_tournament.max_team_slots then raise exception 'This tournament is full'; end if;
  insert into public.tournament_team_registrations(tournament_key, team_id, registered_by, amount_paid, payment_reference)
  values (p_tournament_key, p_team_id, auth.uid(), selected_tournament.registration_fee, p_payment_reference);
  return jsonb_build_object('registered', true, 'message', 'Payment successful — your team is registered.');
exception
  when unique_violation then raise exception 'This team is already registered for the tournament';
end;
$$;

revoke all on function public.register_team_for_tournament(uuid, text, text) from public;
grant execute on function public.register_team_for_tournament(uuid, text, text) to authenticated;

grant select on public.tournaments to authenticated;
grant select on public.tournament_team_registrations to authenticated;
